/* Bài 9 · Năng lượng, điện áp, dòng điện, điện trở và công suất (CM01.02) — sinh bởi tools/author/maytinh/m09.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l9"),{id:"l9",scenarios:[{"label": "Ví dụ: Định luật Ohm: 5 V qua 1 kΩ", "note": "Tính dòng, rồi công suất tỏa nhiệt trên điện trở.", "steps": [{"t": "Nguồn 5 V nối điện trở 1 kΩ", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch một điện trở\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">5 V<\/text><path d=\"M40 40 H140\" class=\"wire\"/><rect x=\"140\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M200 40 H280 V150 H40\" class=\"wire\"/><text x=\"150\" y=\"26\">1 kΩ<\/text><text x=\"210\" y=\"100\" class=\"acc\">I = ?<\/text><\/svg>", "say": "<p>Điện áp nguồn đặt lên hai đầu điện trở. Dòng điện bằng bao nhiêu?<\/p>"}, {"t": "I = V ÷ R = 5 mA", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch một điện trở\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire on\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire on\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">5 V<\/text><path d=\"M40 40 H140\" class=\"wire on\"/><rect x=\"140\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M200 40 H280 V150 H40\" class=\"wire on\"/><text x=\"150\" y=\"26\">1 kΩ<\/text><text x=\"210\" y=\"100\" class=\"acc\">I = 5 mA<\/text><path d=\"M240 34 l10 6 l-10 6\" class=\"wire on\"/><\/svg><p class=\"mt-calc\">I = V ÷ R = 5 V ÷ 1 000 Ω = <b>0,005 A = 5 mA<\/b><\/p>", "ask": {"q": "5 V đặt lên điện trở 1 kΩ. Dòng điện bằng bao nhiêu?", "o": ["5 A", "5 mA", "0,2 A"], "a": 1}}, {"t": "P = V × I = 25 mW, tất cả thành nhiệt", "html": "<p class=\"mt-calc\">P = V × I = 5 × 0,005 = <b>0,025 W<\/b> · kiểm tra: I²R = 0,005² × 1 000 = 0,025 W ✓<\/p>", "say": "<p>Năng lượng điện qua điện trở biến thành nhiệt. Điện trở phải chịu được công suất này: loại nhỏ thường gặp có định mức 0,25 W, dư nhiều so với 0,025 W.<\/p>"}]}, {"label": "Ví dụ: Hai điện trở nối tiếp (chia áp)", "note": "Cùng dòng; điện áp chia theo tỉ lệ điện trở.", "steps": [{"t": "12 V, hai điện trở 4 Ω và 2 Ω nối tiếp", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch hai điện trở nối tiếp\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">12 V<\/text><path d=\"M40 40 H90\" class=\"wire\"/><rect x=\"90\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M150 40 H190\" class=\"wire\"/><rect x=\"190\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M250 40 H300 V150 H40\" class=\"wire\"/><text x=\"94\" y=\"26\">R1 = 4 Ω<\/text><text x=\"194\" y=\"26\">R2 = 2 Ω<\/text><text x=\"94\" y=\"72\" class=\"warm\"><\/text><text x=\"194\" y=\"72\" class=\"warm\"><\/text><text x=\"150\" y=\"140\" class=\"acc\"><\/text><\/svg>", "say": "<p>Nối tiếp: chỉ có một đường, nên <b>cùng một dòng<\/b> đi qua cả hai điện trở.<\/p>"}, {"t": "R tương đương = 4 + 2 = 6 Ω → I = 2 A", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch hai điện trở nối tiếp\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire on\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire on\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">12 V<\/text><path d=\"M40 40 H90\" class=\"wire on\"/><rect x=\"90\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M150 40 H190\" class=\"wire on\"/><rect x=\"190\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M250 40 H300 V150 H40\" class=\"wire on\"/><text x=\"94\" y=\"26\">R1 = 4 Ω<\/text><text x=\"194\" y=\"26\">R2 = 2 Ω<\/text><text x=\"94\" y=\"72\" class=\"warm\"><\/text><text x=\"194\" y=\"72\" class=\"warm\"><\/text><text x=\"150\" y=\"140\" class=\"acc\">I = 2 A<\/text><\/svg><p class=\"mt-calc\">R<sub>tđ<\/sub> = R1 + R2 = 6 Ω · I = 12 ÷ 6 = <b>2 A<\/b><\/p>"}, {"t": "Chia áp: V1 = 8 V, V2 = 4 V", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch hai điện trở nối tiếp\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire on\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire on\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">12 V<\/text><path d=\"M40 40 H90\" class=\"wire on\"/><rect x=\"90\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M150 40 H190\" class=\"wire on\"/><rect x=\"190\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M250 40 H300 V150 H40\" class=\"wire on\"/><text x=\"94\" y=\"26\">R1 = 4 Ω<\/text><text x=\"194\" y=\"26\">R2 = 2 Ω<\/text><text x=\"94\" y=\"72\" class=\"warm\">V1 = 8 V<\/text><text x=\"194\" y=\"72\" class=\"warm\">V2 = 4 V<\/text><text x=\"150\" y=\"140\" class=\"acc\">I = 2 A<\/text><\/svg><p class=\"mt-calc\">V1 = I × R1 = 8 V · V2 = I × R2 = 4 V · 8 + 4 = 12 V ✓<\/p>", "ask": {"q": "Dòng 2 A qua R1 = 4 Ω. Điện áp trên R1 bằng bao nhiêu?", "o": ["2 V", "8 V", "12 V"], "a": 1}, "say": "<p>Tổng điện áp trên các điện trở bằng điện áp nguồn (định luật Kirchhoff về điện áp). Điện trở lớn hơn nhận phần điện áp lớn hơn: đó là mạch chia áp.<\/p>"}]}, {"label": "Ví dụ: Hai điện trở song song", "note": "Cùng điện áp; dòng chia, điện trở tương đương nhỏ hơn mỗi nhánh.", "steps": [{"t": "12 V, hai điện trở 4 Ω và 2 Ω song song", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 180\" role=\"img\" aria-label=\"Sơ đồ mạch hai điện trở song song\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"92\" class=\"wire\"/><line x1=\"40\" y1=\"108\" x2=\"40\" y2=\"160\" class=\"wire\"/><line x1=\"24\" y1=\"92\" x2=\"56\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"108\" x2=\"48\" y2=\"108\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"90\" class=\"sm\">+<\/text><text x=\"6\" y=\"134\">12 V<\/text><path d=\"M40 40 H280 M40 160 H280\" class=\"wire\"/><line x1=\"170\" y1=\"40\" x2=\"170\" y2=\"72\" class=\"wire\"/><rect x=\"162\" y=\"72\" width=\"16\" height=\"50\" rx=\"2\" class=\"part\"/><line x1=\"170\" y1=\"122\" x2=\"170\" y2=\"160\" class=\"wire\"/><line x1=\"280\" y1=\"40\" x2=\"280\" y2=\"72\" class=\"wire\"/><rect x=\"272\" y=\"72\" width=\"16\" height=\"50\" rx=\"2\" class=\"part\"/><line x1=\"280\" y1=\"122\" x2=\"280\" y2=\"160\" class=\"wire\"/><text x=\"182\" y=\"92\">4 Ω<\/text><text x=\"182\" y=\"112\" class=\"acc\"><\/text><text x=\"292\" y=\"92\">2 Ω<\/text><text x=\"292\" y=\"112\" class=\"acc\"><\/text><text x=\"80\" y=\"30\" class=\"acc\"><\/text><\/svg>", "say": "<p>Song song: mỗi điện trở nối thẳng vào hai cực nguồn, nên <b>cùng điện áp<\/b> 12 V.<\/p>"}, {"t": "Mỗi nhánh: I1 = 3 A, I2 = 6 A", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 180\" role=\"img\" aria-label=\"Sơ đồ mạch hai điện trở song song\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"92\" class=\"wire on\"/><line x1=\"40\" y1=\"108\" x2=\"40\" y2=\"160\" class=\"wire on\"/><line x1=\"24\" y1=\"92\" x2=\"56\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"108\" x2=\"48\" y2=\"108\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"90\" class=\"sm\">+<\/text><text x=\"6\" y=\"134\">12 V<\/text><path d=\"M40 40 H280 M40 160 H280\" class=\"wire on\"/><line x1=\"170\" y1=\"40\" x2=\"170\" y2=\"72\" class=\"wire on\"/><rect x=\"162\" y=\"72\" width=\"16\" height=\"50\" rx=\"2\" class=\"part\"/><line x1=\"170\" y1=\"122\" x2=\"170\" y2=\"160\" class=\"wire on\"/><line x1=\"280\" y1=\"40\" x2=\"280\" y2=\"72\" class=\"wire on\"/><rect x=\"272\" y=\"72\" width=\"16\" height=\"50\" rx=\"2\" class=\"part\"/><line x1=\"280\" y1=\"122\" x2=\"280\" y2=\"160\" class=\"wire on\"/><text x=\"182\" y=\"92\">4 Ω<\/text><text x=\"182\" y=\"112\" class=\"acc\">I1 = 3 A<\/text><text x=\"292\" y=\"92\">2 Ω<\/text><text x=\"292\" y=\"112\" class=\"acc\">I2 = 6 A<\/text><text x=\"80\" y=\"30\" class=\"acc\"><\/text><\/svg><p class=\"mt-calc\">I1 = 12 ÷ 4 = 3 A · I2 = 12 ÷ 2 = 6 A<\/p>", "ask": {"q": "Nhánh nào có dòng lớn hơn?", "o": ["Nhánh 4 Ω", "Nhánh 2 Ω", "Bằng nhau"], "a": 1}}, {"t": "Tổng dòng 9 A, R tương đương ≈ 1,33 Ω", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 180\" role=\"img\" aria-label=\"Sơ đồ mạch hai điện trở song song\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"92\" class=\"wire on\"/><line x1=\"40\" y1=\"108\" x2=\"40\" y2=\"160\" class=\"wire on\"/><line x1=\"24\" y1=\"92\" x2=\"56\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"108\" x2=\"48\" y2=\"108\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"90\" class=\"sm\">+<\/text><text x=\"6\" y=\"134\">12 V<\/text><path d=\"M40 40 H280 M40 160 H280\" class=\"wire on\"/><line x1=\"170\" y1=\"40\" x2=\"170\" y2=\"72\" class=\"wire on\"/><rect x=\"162\" y=\"72\" width=\"16\" height=\"50\" rx=\"2\" class=\"part\"/><line x1=\"170\" y1=\"122\" x2=\"170\" y2=\"160\" class=\"wire on\"/><line x1=\"280\" y1=\"40\" x2=\"280\" y2=\"72\" class=\"wire on\"/><rect x=\"272\" y=\"72\" width=\"16\" height=\"50\" rx=\"2\" class=\"part\"/><line x1=\"280\" y1=\"122\" x2=\"280\" y2=\"160\" class=\"wire on\"/><text x=\"182\" y=\"92\">4 Ω<\/text><text x=\"182\" y=\"112\" class=\"acc\">I1 = 3 A<\/text><text x=\"292\" y=\"92\">2 Ω<\/text><text x=\"292\" y=\"112\" class=\"acc\">I2 = 6 A<\/text><text x=\"80\" y=\"30\" class=\"acc\">I = 9 A<\/text><\/svg><p class=\"mt-calc\">I = I1 + I2 = 9 A · 1/R<sub>tđ<\/sub> = 1/4 + 1/2 → R<sub>tđ<\/sub> = 4/3 ≈ <b>1,33 Ω<\/b> · kiểm tra 12 ÷ 4/3 = 9 A ✓<\/p>", "say": "<p>Thêm nhánh song song làm điện trở tương đương <b>nhỏ hơn<\/b> nhánh nhỏ nhất và tổng dòng lớn hơn. Đó là lý do cắm quá nhiều thiết bị vào một ổ có thể làm quá tải dây dẫn.<\/p>"}]}, {"label": "Ví dụ: Điện trở hạn dòng cho LED", "note": "Phần điện áp còn lại đặt lên điện trở; chọn giá trị chuẩn.", "steps": [{"t": "Đèn LED 5 V: cần điện trở nối tiếp", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch đèn LED có điện trở hạn dòng\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">5 V<\/text><path d=\"M40 40 H120\" class=\"wire\"/><rect x=\"120\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M180 40 H260 V70\" class=\"wire\"/><path d=\"M248 70 H272 L260 92 Z\" class=\"soft\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"248\" y1=\"92\" x2=\"272\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M260 92 V150 H40\" class=\"wire\"/><text x=\"126\" y=\"26\">R = ?<\/text><text x=\"282\" y=\"110\" class=\"sm\">LED đỏ (giả định 2,0 V, 10 mA)<\/text><text x=\"120\" y=\"140\" class=\"acc\"><\/text><\/svg>", "say": "<p>LED <b>không<\/b> tuân theo định luật Ohm: khi điện áp vượt khoảng điện áp mở, dòng tăng rất nhanh. Điện trở nối tiếp giới hạn dòng.<\/p>"}, {"t": "R = (5 − 2) ÷ 0,01 = 300 Ω", "html": "<p class=\"mt-calc\">Điện áp còn lại trên R: 5 − 2,0 = 3,0 V · R = 3,0 ÷ 0,010 = <b>300 Ω<\/b><\/p>", "ask": {"q": "Nguồn 5 V, LED 2,0 V, muốn 10 mA. Điện trở cần bao nhiêu?", "o": ["500 Ω", "300 Ω", "200 Ω"], "a": 1}}, {"t": "Chọn giá trị chuẩn 330 Ω → I ≈ 9,1 mA", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch đèn LED có điện trở hạn dòng\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire on\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire on\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">5 V<\/text><path d=\"M40 40 H120\" class=\"wire on\"/><rect x=\"120\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M180 40 H260 V70\" class=\"wire on\"/><path d=\"M248 70 H272 L260 92 Z\" class=\"warm\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"248\" y1=\"92\" x2=\"272\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M276 72 l12 -8 M280 82 l12 -8\" class=\"wire on\"/><path d=\"M260 92 V150 H40\" class=\"wire on\"/><text x=\"126\" y=\"26\">R = 330 Ω<\/text><text x=\"282\" y=\"110\" class=\"sm\">LED sáng<\/text><text x=\"120\" y=\"140\" class=\"acc\">I ≈ 9,1 mA<\/text><\/svg><p class=\"mt-calc\">I = 3,0 ÷ 330 ≈ <b>9,1 mA<\/b> · P<sub>R<\/sub> = I²R ≈ 0,027 W<\/p>", "say": "<p>Điện trở bán theo dãy giá trị chuẩn (dãy E12 có 270, 330, 390 Ω…). Chọn giá trị chuẩn lớn hơn gần nhất cho dòng nhỏ hơn một chút, an toàn hơn. Điện áp thật của LED phụ thuộc màu và dòng: luôn tra tài liệu của linh kiện.<\/p>"}]}, {"label": "Ví dụ: Điện năng của máy tính trong tháng", "note": "Công suất là tốc độ; năng lượng là công suất × thời gian.", "steps": [{"t": "Máy tính trung bình 200 W, 8 giờ mỗi ngày", "html": "<p class=\"mt-calc\">Giả định: công suất trung bình cả máy và màn hình là 200 W<\/p>", "say": "<p>Công suất (W) là tốc độ dùng năng lượng; năng lượng = công suất × thời gian.<\/p>"}, {"t": "Một ngày: 200 W × 8 h = 1,6 kWh", "html": "<p class=\"mt-calc\">W = P × t = 200 × 8 = 1 600 Wh = <b>1,6 kWh<\/b><\/p>"}, {"t": "Một tháng 30 ngày: 48 kWh", "html": "<p class=\"mt-calc\">1,6 × 30 = <b>48 kWh<\/b> = 48 × 3,6 MJ = 172,8 MJ<\/p><div class=\"mt-bars\"><div><span>1 ngày<\/span><span><i class=\"\" style=\"width:3.3%\"><\/i><em>1,6 kWh<\/em><\/span><\/div><div><span>30 ngày<\/span><span><i class=\"w\" style=\"width:100.0%\"><\/i><em>48 kWh<\/em><\/span><\/div><\/div>", "ask": {"q": "1,6 kWh mỗi ngày, trong 30 ngày là bao nhiêu kWh?", "o": ["48 kWh", "1,6 kWh", "160 kWh"], "a": 0}, "say": "<p>“Số điện” trên hóa đơn chính là kWh. 1 kWh = 1 000 W × 3 600 s = 3,6 × 10⁶ J.<\/p>"}]}, {"label": "Bẫy: Quên đổi kΩ sang Ω", "note": "Sai 1 000 lần về dòng và công suất.", "steps": [{"t": "Tính I = 5 V ÷ 1 kΩ", "html": "<p class=\"mt-calc\">Bước đúng: đổi 1 kΩ = 1 000 Ω trước khi chia<\/p>", "say": "<p>Lỗi hay gặp: chia 5 cho 1 vì thấy chữ “1 kΩ”.<\/p>"}, {"t": "Sai: I = 5 ÷ 1 = 5 A, P = 25 W", "html": "<p class=\"mt-calc\">5 ÷ 1 = 5 A · P = 5 × 5 = <b>25 W<\/b><\/p><div class=\"mt-bars\"><div><span>Tính sai<\/span><span><i class=\"e\" style=\"width:100.0%\"><\/i><em>25 W<\/em><\/span><\/div><\/div>", "ask": {"q": "Quên đổi kΩ sang Ω thì kết quả dòng điện sai bao nhiêu lần?", "o": ["10 lần", "1 000 lần", "Không sai"], "a": 1}}, {"t": "Đúng: I = 5 mA, P = 25 mW", "html": "<p class=\"mt-calc\">5 ÷ 1 000 = 0,005 A · P = 0,025 W<\/p><div class=\"mt-bars\"><div><span>Tính sai<\/span><span><i class=\"e\" style=\"width:100.0%\"><\/i><em>25 W<\/em><\/span><\/div><div><span>Đúng<\/span><span><i class=\"o\" style=\"width:0.5%\"><\/i><em>0,025 W<\/em><\/span><\/div><\/div>", "say": "<p>Sai 1 000 lần về dòng và công suất. Quy tắc: đổi mọi đại lượng về đơn vị cơ bản (V, A, Ω, W, s) trước khi thay vào công thức, rồi mới đổi kết quả sang mA, mW cho dễ đọc.<\/p>"}]}, {"label": "Lỗi: Nối LED thẳng vào 5 V", "note": "LED không tuân theo định luật Ohm; thiếu điện trở là quá dòng.", "steps": [{"t": "Nối LED thẳng vào 5 V, không điện trở", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch đèn LED có điện trở hạn dòng\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire on\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire on\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">5 V<\/text><path d=\"M40 40 H120\" class=\"wire on\"/><rect x=\"120\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M180 40 H260 V70\" class=\"wire on\"/><path d=\"M248 70 H272 L260 92 Z\" class=\"warm\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"248\" y1=\"92\" x2=\"272\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M276 72 l12 -8 M280 82 l12 -8\" class=\"wire on\"/><path d=\"M260 92 V150 H40\" class=\"wire on\"/><text x=\"126\" y=\"26\">R = 0 (bỏ điện trở)<\/text><text x=\"282\" y=\"110\" class=\"sm\">LED quá dòng!<\/text><text x=\"120\" y=\"140\" class=\"acc\">I rất lớn<\/text><\/svg>", "say": "<p>Nghĩ rằng LED “tự lấy đủ dòng”. Nhưng LED không có điện trở cố định để giới hạn dòng như định luật Ohm.<\/p>"}, {"t": "Dòng chỉ bị giới hạn bởi dây và nguồn: vượt định mức", "html": "<p class=\"mt-calc\">Điện áp trên LED bị ép lên 5 V, cao hơn nhiều điện áp mở → dòng tăng vọt, vượt định mức (LED chỉ thị nhỏ thường chỉ cỡ vài chục mA)<\/p>", "ask": {"q": "LED đỏ nối thẳng vào 5 V không điện trở. Điều gì có thể xảy ra?", "o": ["LED sáng bình thường", "Dòng vượt định mức, LED nóng và hỏng", "Không có dòng"], "a": 1}}, {"t": "Sửa: thêm điện trở hạn dòng 330 Ω", "html": "<svg class=\"mt-svg\" viewBox=\"0 0 360 170\" role=\"img\" aria-label=\"Sơ đồ mạch đèn LED có điện trở hạn dòng\"><line x1=\"40\" y1=\"40\" x2=\"40\" y2=\"87\" class=\"wire on\"/><line x1=\"40\" y1=\"103\" x2=\"40\" y2=\"150\" class=\"wire on\"/><line x1=\"24\" y1=\"87\" x2=\"56\" y2=\"87\" stroke=\"currentColor\" stroke-width=\"3\"/><line x1=\"32\" y1=\"103\" x2=\"48\" y2=\"103\" stroke=\"currentColor\" stroke-width=\"3\"/><text x=\"60\" y=\"85\" class=\"sm\">+<\/text><text x=\"6\" y=\"129\">5 V<\/text><path d=\"M40 40 H120\" class=\"wire on\"/><rect x=\"120\" y=\"32\" width=\"60\" height=\"16\" rx=\"2\" class=\"part\"/><path d=\"M180 40 H260 V70\" class=\"wire on\"/><path d=\"M248 70 H272 L260 92 Z\" class=\"warm\" stroke=\"currentColor\" stroke-width=\"2\"/><line x1=\"248\" y1=\"92\" x2=\"272\" y2=\"92\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M276 72 l12 -8 M280 82 l12 -8\" class=\"wire on\"/><path d=\"M260 92 V150 H40\" class=\"wire on\"/><text x=\"126\" y=\"26\">R = 330 Ω<\/text><text x=\"282\" y=\"110\" class=\"sm\">LED sáng an toàn<\/text><text x=\"120\" y=\"140\" class=\"acc\">I ≈ 9,1 mA<\/text><\/svg>", "say": "<p>Chân ra của vi điều khiển cũng có giới hạn dòng; nối LED thẳng có thể hỏng cả chân ra. Khóa Nền tảng vi điều khiển – vi xử lý sẽ tính kỹ phần này.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l9"),"l9",[{"kind": "num", "t": "Định luật Ohm và công suất", "d": "<p>Đổi về đơn vị cơ bản trước khi tính. Ghi kết quả theo đơn vị đề yêu cầu.<\/p>", "items": [{"q": "9 V đặt lên điện trở 450 Ω. Dòng điện?", "a": 20.0, "tol": 0.01, "unit": "mA"}, {"q": "Dòng 0,5 A qua điện trở 24 Ω. Điện áp trên điện trở?", "a": 12, "tol": 0.01, "unit": "V"}, {"q": "Muốn dòng 2 mA khi đặt 3,3 V. Điện trở cần?", "a": 1650, "tol": 0.5, "unit": "Ω"}, {"q": "Thiết bị 12 V tiêu thụ 2 A. Công suất?", "a": 24, "tol": 0.01, "unit": "W"}], "hints": ["V = I · R, nên I = V ÷ R và R = V ÷ I.", "Đổi 2 mA = 0,002 A trước khi chia; đổi kết quả A sang mA bằng cách nhân 1 000.", "P = V · I."], "why": "9 ÷ 450 = 0,02 A = 20 mA; 0,5 × 24 = 12 V; 3,3 ÷ 0,002 = 1 650 Ω; 12 × 2 = 24 W."}, {"kind": "num", "t": "Nối tiếp và song song", "d": "<p>Làm tròn 2 chữ số thập phân.<\/p>", "items": [{"q": "Nguồn 10 V, R1 = 3 kΩ nối tiếp R2 = 2 kΩ. Dòng điện?", "a": 2, "tol": 0.01, "unit": "mA"}, {"q": "Cùng mạch trên: điện áp trên R2?", "a": 4, "tol": 0.01, "unit": "V"}, {"q": "6 Ω song song 3 Ω. Điện trở tương đương?", "a": 2, "tol": 0.01, "unit": "Ω"}, {"q": "Mạch song song trên nối nguồn 6 V. Tổng dòng?", "a": 3, "tol": 0.01, "unit": "A"}], "hints": ["Nối tiếp: R<sub>tđ<\/sub> = R1 + R2 = 5 kΩ.", "Điện áp trên R2 = I × R2 (cẩn thận đơn vị mA và kΩ: mA × kΩ = V).", "Song song: 1/R = 1/6 + 1/3 = 1/2."], "why": "10 V ÷ 5 kΩ = 2 mA; 2 mA × 2 kΩ = 4 V; 1/6 + 1/3 = 1/2 → 2 Ω; 6 V ÷ 2 Ω = 3 A (kiểm tra: 1 A + 2 A)."}, {"kind": "num", "t": "LED và điện năng", "d": "<p>Dùng giả định trong đề. Làm tròn 2 chữ số thập phân.<\/p>", "items": [{"q": "Nguồn 3,3 V, LED 2,0 V, muốn 5 mA. Điện trở cần?", "a": 259.99999999999994, "tol": 0.5, "unit": "Ω"}, {"q": "Màn hình 65 W bật 10 giờ. Điện năng?", "a": 0.65, "tol": 0.001, "unit": "kWh"}, {"q": "1 kWh bằng bao nhiêu megajun?", "a": 3.6, "tol": 0.001, "unit": "MJ"}, {"q": "Máy 150 W, 6 giờ mỗi ngày, 30 ngày. Điện năng?", "a": 27, "tol": 0.01, "unit": "kWh"}], "hints": ["Điện áp trên điện trở = 3,3 − 2,0 = 1,3 V.", "Wh = W × giờ; chia 1 000 để ra kWh.", "1 kWh = 1 000 W × 3 600 s."], "why": "1,3 ÷ 0,005 = 260 Ω; 65 × 10 = 650 Wh = 0,65 kWh; 1 000 × 3 600 = 3 600 000 J = 3,6 MJ; 150 × 6 × 30 = 27 000 Wh = 27 kWh."}]);

makeQuiz("quiz9","score9",[{"q": "1 vôn (1 V) bằng bao nhiêu?", "o": ["1 C/s", "1 W·s", "1 J/C", "1 A·Ω²"], "a": 2, "e": "Điện áp là năng lượng trên mỗi đơn vị điện tích: 1 V = 1 J/C. 1 C/s là định nghĩa của ampe."}, {"q": "Dòng 0,2 A chạy qua điện trở 100 Ω. Công suất tỏa nhiệt bằng bao nhiêu?", "o": ["20 W", "4 W", "0,04 W", "500 W"], "a": 1, "e": "P = I²R = 0,2² × 100 = 0,04 × 100 = 4 W. Đáp án 20 W là nhầm thành I × R (đó là điện áp, 20 V)."}, {"q": "Hai điện trở 6 Ω mắc song song. Điện trở tương đương bằng bao nhiêu?", "o": ["12 Ω", "6 Ω", "1/3 Ω", "3 Ω"], "a": 3, "e": "1/R = 1/6 + 1/6 = 1/3 → R = 3 Ω. Mắc song song làm điện trở nhỏ đi; 12 Ω là kết quả của nối tiếp."}, {"q": "Định luật Ohm V = I · R áp dụng đúng cho linh kiện nào?", "o": ["Điện trở thông thường ở nhiệt độ ổn định", "Đèn LED", "Diode silicon", "Mọi linh kiện điện tử"], "a": 0, "e": "Điện trở thông thường gần như tuyến tính. Dòng qua LED, diode tăng theo hàm mũ của điện áp nên không có một giá trị R cố định."}, {"q": "Một máy dùng 250 W chạy 4 giờ tiêu thụ bao nhiêu điện năng?", "o": ["1 kWh", "62,5 kWh", "1 000 kWh", "0,25 kWh"], "a": 0, "e": "250 W × 4 h = 1 000 Wh = 1 kWh. Đáp án 1 000 kWh là quên đổi Wh sang kWh."}]);

